/* Doodles lifted from the photos in portfolio_img (ink only, transparent background).
   Embedded as data URIs so the canvas stays untainted even when the page is opened
   straight from disk. Source PNGs: images/doodles/. Strokes are thickened so they
   survive the coarse dither bars at small sizes. */
window.DOODLES = {
  heart: 'data:image/png;base64,',
  plane: 'data:image/png;base64,',
  fish: 'data:image/png;base64,',
};

